import 'package:flutter/material.dart';
import '../core/database/database_helper.dart';

class ReportsScreen extends StatelessWidget{const ReportsScreen({super.key});@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[Text('التقارير',style:Theme.of(c).textTheme.headlineSmall?.copyWith(color:const Color(0xFF0D47A1),fontWeight:FontWeight.bold)),const SizedBox(height:18),_button(c,'تقرير المبيعات',Icons.point_of_sale,()=>_show(c,'تقرير المبيعات')), _button(c,'تقرير الأرباح والخسائر',Icons.analytics,()=>_show(c,'تقرير الأرباح والخسائر')), _button(c,'كشف حساب عميل',Icons.person_search,()=>_show(c,'كشف حساب عميل'))]);Widget _button(BuildContext c,String text,IconData icon,VoidCallback onTap)=>Padding(padding:const EdgeInsets.only(bottom:14),child:SizedBox(height:64,width:double.infinity,child:FilledButton.icon(onPressed:onTap,icon:Icon(icon),label:Text(text,style:const TextStyle(fontSize:17)))));void _show(BuildContext c,String title)async{final x=await DatabaseHelper.instance.summary();if(!c.mounted)return;showDialog(context:c,builder:(_)=>AlertDialog(title:Text(title),content:Text('إجمالي المبيعات: ${(x['sales']??0).toStringAsFixed(2)} ر.س\nصافي الربح: ${(x['profit']??0).toStringAsFixed(2)} ر.س'),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('إغلاق'))]));}}
